#!/usr/bin/env python3
# =====================================================================
#  apply_broker_truth.py  —  fence BROKER_TRUTH_20261114
#
#  ⚠ LIVE ORDER PATH — Icarus, Timberwolf, Tigris, Velvet (exits, GTT
#  monitors, restart adoption). Install BEFORE the next live session.
#
#  WHAT WENT WRONG ON 13 NOV (three strategies live on one account)
#   A. 07:43, app started before the Kite login — and again 05:00 on the
#      14th (overnight session flush): get_gtts() / get_open_positions()
#      answer [] when they CANNOT read. The Icarus GTT monitor read that as
#      "GTTs gone AND position gone" and booked both carried shorts as
#      BROKER_EXIT. At 09:16 the app had nothing to square off, the shorts
#      and their GTTs stayed live, and they had to be closed by hand.
#      (Until 12 Nov a second bug hid this one: the pre-market teardown
#      falsely "confirmed" every GTT gone in the first seconds and emptied
#      the ids the monitor watches. Fixing that on the 12th exposed this.)
#      Timberwolf's monitor has the identical logic.
#   B. Velvet and Timberwolf were short the SAME strike. Every exit path
#      treats the broker's net position on a contract as its own:
#      Velvet's buy-back filled, the net still read −130 (Timberwolf's),
#      Velvet called it "not confirmed" and bought 130 more — closing
#      Timberwolf's short and leaving its hedge. Timberwolf's own check
#      meanwhile paged "broker −260, expected −130". Icarus, Tigris and
#      Timberwolf exits share the same assumption.
#
#  THE RULES NOW (app/execution/broker_truth.py, used by all four)
#   1. Unreadable is never "empty": strict reads, None = unreadable.
#   2. Outside the derivatives session (09:15–15:40, trading days) a
#      monitor infers nothing — a GTT cannot fire and nobody can exit.
#   3. "GTT gone + position gone" is booked only with the exit ORDER that
#      proves it. No order → one page, nothing booked.
#   4. A live ledger knows which strategy holds which contract (each
#      manager registers its legs and reserves an entry's contracts before
#      its first order; strategies outside the core four are read from
#      their open live rows). A net position is "mine" only when nobody
#      else holds the contract; otherwise the strategy acts on its own
#      orders alone.
#   5. Order truth first, in every exit: my own COMPLETE fills for the
#      whole leg ARE the exit. After a partial fill the retry closes only
#      what is left of MY quantity.
#   Sharing a strike is therefore allowed and handled; strike selection is
#   unchanged (no parity impact).
#
#  FILES
#   execution/broker_truth.py (new) · ic_gtt_monitor.py · tma2_gtt_monitor.py
#   ic_group_manager.py · tma2_trade_manager.py (+ recon and restart
#   adoption aware of other holders) · tsg_manager.py · vet_manager.py
#   five existing test files: one line each to open the simulated session /
#   give their fake broker a strict read
#
#  TESTS
#   engine/test_fleet_live.py (new, 362 checks): the four REAL managers and
#   both REAL GTT monitors on ONE shared account, colliding on shorts and
#   wings on purpose — 13 Nov replayed both ways, GTT stops / gaps on shared
#   strikes, entry unwinds, partial fills + retries, overnight carry → start
#   before login → 09:16 square-off, mid-day outage, simultaneous entries
#   and exits in threads, restart with shared contracts, and 150 randomised
#   days. After every step: broker positions == the strategies' books,
#   every active GTT has an owner, nothing left working. The code that was
#   live on 13 Nov fails it with that day's exact messages.
#   execution/test_broker_truth.py (new, 27 checks) + every Icarus,
#   Timberwolf, Tigris, Velvet, router, recon and execution suite.
#
#  Run ONLY this script, outside market hours:
#     cd ~/dev/scalp-app && python3 apply_broker_truth.py
#  Options: --repo PATH  --skip-tests  --allow-dirty  --rollback
#  Then: ./desktop/build-scalp.sh both, restart the app.
# =====================================================================
import base64, hashlib, json, os, py_compile, shutil, subprocess, sys, tempfile, zlib

FENCE = "BROKER_TRUTH_20261114"
ITEMS = json.loads(r'''[{"path": "backend/app/execution/broker_truth.py", "orig": null, "new": "4913c6fbf79878e201e088fe057b6a913ca7a4716d213f8f68934de69eba07f5", "blob": ""}, {"path": "backend/app/engine/ic/ic_gtt_monitor.py", "orig": "370f54ee581a00db2767def60c265c26376a8b992f7fc5f4dc015325687f9cb4", "new": "04a3ed0961efacef411a3f1c0a86cd71ed9295cd4e4f90164a2e65f3bd9fdd04", "blob": ""}, {"path": "backend/app/engine/ic/ic_group_manager.py", "orig": "8690a960c76043a5c021105a18b0cd0a4fa9af0a4f6678ce20d24b72b79edc9c", "new": "1ea7c00525811f308ab5669636be529f38cb2b0be469d808e68629165adaf03f", "blob": ""}, {"path": "backend/app/engine/tma2/tma2_gtt_monitor.py", "orig": "2e580d79e02fe5f44ff9dc9cf2f391b803c9ef3f291bd2257c61c0beee3d23a0", "new": "d3e9137392a33421970459528d7f0f0405473c4a3cb736a8baf64db18639d0b0", "blob": ""}, {"path": "backend/app/engine/tma2/tma2_trade_manager.py", "orig": "7f25b31df8b99546369c20fd14d3bbbc1e099f26ff6cc3920b42a86b090cd696", "new": "453e97991de2568a3fc6b2d62b04c597b3dd0b5ce2d496e1c1a88a5bfb8bd462", "blob": ""}, {"path": "backend/app/engine/tsg/tsg_manager.py", "orig": "82dcead0b4497423608a8a5fd00b336f74e931a6fe465e9107c984f4e2fd5b05", "new": "06c144adac0ddc72b17b768c1930dc639f777676095c1be4ab57b2ceefb6445f", "blob": ""}, {"path": "backend/app/engine/vet/vet_manager.py", "orig": "bd5d34d244a2a34ce8c02366514527fb947785debfb685191d451148da33d3fa", "new": "26da4cf41bd3faaff8f9929c3690171245e83bcb98faaf56ad01c97c8ac513ea", "blob": ""}, {"path": "backend/app/engine/ic/test_ic_engine_monitor_eod.py", "orig": "7d739575d5e0f604ca1b2879a662c977063e51dc45d0d17940d4569be377b536", "new": "efde0fd1b580ceba04d2a52d1b3a54aa372fbecc33e0118b3e3c76c9fd00ae32", "blob": ""}, {"path": "backend/app/engine/ic/test_ic_group_manager.py", "orig": "ee10a0e4e2d9452e1ba0c520d2d471d98b7101411a8529a8fbd98603d41959be", "new": "94e830800faa5ae81a128f3512b424f45f61c4be9996fd9a7783b93dabaffeaa", "blob": ""}, {"path": "backend/app/engine/tma2/test_tma2_e2e.py", "orig": "cc1ff21503a1d877c830eb850204dec4194ed6c8eca5a0b333ebce67b996e661", "new": "d0e60f042596b2d3a01fa8636b0264f5a8b2b18c6b782e8a6c0971b22ec1d8a1", "blob": ""}, {"path": "backend/app/engine/tma2/test_tma2_exit_paths.py", "orig": "dca54b71456bfa45834f63b865cb69bf77acc79ceaba1ad589a46bc448da0a1c", "new": "d763479f6fbf31abf49411231dc36a9a87e77c24f584b666d5fa9fe09f72bf2c", "blob": ""}, {"path": "backend/app/engine/tma2/test_tma_fill_truth.py", "orig": "670e2137ed1c16b93247d1991ca095810adef794f578f7d5752fd6967c868aff", "new": "ef31d3dae93dd6ef98827099ff0ecc529d0fb29fef1a150269e30f66f27a4361", "blob": ""}, {"path": "backend/app/execution/test_broker_truth.py", "orig": null, "new": "6a6e0a7621b7d33920b3e5830b6e36c150ed472f61af2319befbb41463f649c8", "blob": ""}, {"path": "backend/app/engine/test_fleet_live.py", "orig": null, "new": "1d0fba3f6d7de1946ce8549d0e76d99f8f7ce633bf26ce78f6782f102a8b4a44", "blob": ""}]''')
BUILD_COPIES = {"backend/": "desktop/src-tauri/backend/", "frontend/": "desktop/src-tauri/frontend/"}
TESTS = ["app/execution/test_broker_truth.py", "app/engine/test_fleet_live.py",
         "app/engine/ic/test_ic_gtt_strict.py",          # runs the IC suites one by one
         "app/engine/ic/test_ic_wing_fast_fill.py",
         "app/engine/tma2/test_tma2_e2e.py", "app/engine/tma2/test_tma2_exit_paths.py",
         "app/engine/tma2/test_tma_fill_truth.py", "app/engine/tma2/test_tma2_entry_paths.py",
         "app/engine/tma2/test_tma_paper_fallback.py",
         "app/engine/tsg/test_tsg_e2e.py", "app/engine/tsg/test_tsg_exit_confirm.py",
         "app/engine/tsg/test_tsg_wing_guard.py",
         "app/engine/vet/test_vet_e2e.py", "app/engine/vet/test_vet_manager.py",
         "app/engine/vet/test_vet_live_confirm.py", "app/engine/vet/test_vet_wing_far.py",
         "app/engine/vet/test_vet_sltp_live.py", "app/engine/vet/test_vet_live_dte_lots.py",
         "app/engine/test_entry_fast_confirm.py", "app/engine/test_wing_reach.py",
         "app/execution/test_gtt_verify_strict.py", "app/execution/test_wing_fast_fill.py",
         "app/execution/test_order_latency.py", "app/execution/test_execution_router_contract.py",
         "app/recon/test_recon.py", "app/slippage/test_slip.py"]


def sha(b):
    return hashlib.sha256(b).hexdigest()


def say(m):
    print(m, flush=True)


def die(m):
    say(f"\n✗ ABORTED — {m}\n  Nothing was changed.")
    sys.exit(1)


args = sys.argv[1:]
repo = os.path.abspath(os.path.expanduser(args[args.index("--repo") + 1])) if "--repo" in args else os.getcwd()
if not os.path.isdir(os.path.join(repo, "backend", "app")):
    alt = os.path.expanduser("~/dev/scalp-app")
    if os.path.isdir(os.path.join(alt, "backend", "app")):
        repo = alt
    else:
        die(f"{repo} is not the scalp-app repo (no backend/app) — pass --repo PATH")
say(f"repo: {repo}\nfence: {FENCE}")


def targets():
    """(item, absolute path, is_build_copy)"""
    out = []
    for it in ITEMS:
        out.append((it, os.path.join(repo, it["path"]), False))
        for a, b in BUILD_COPIES.items():
            if it["path"].startswith(a):
                p = os.path.join(repo, b + it["path"][len(a):])
                if os.path.isdir(os.path.dirname(p)):
                    out.append((it, p, True))
    return out


# ── rollback mode ────────────────────────────────────────────────────
if "--rollback" in args:
    n = 0
    for it, p, _ in targets():
        bak = p + ".bak-" + FENCE
        if os.path.exists(bak):
            shutil.copy2(bak, p)
            os.remove(bak)
            n += 1
        elif it["orig"] is None and os.path.exists(p):
            with open(p, "rb") as f:
                if sha(f.read()) == it["new"]:
                    os.remove(p)
                    n += 1
    say(f"rolled back {n} file(s)")
    sys.exit(0)

# ── 1. state of every target ─────────────────────────────────────────
plan, done, skipped = [], 0, []
for it, p, build in targets():
    cur = open(p, "rb").read() if os.path.exists(p) else None
    cs = sha(cur) if cur is not None else None
    rel = os.path.relpath(p, repo)
    if cs == it["new"]:
        done += 1
        continue
    if cs == it["orig"]:
        plan.append((it, p, cur, build))
        continue
    if build:
        skipped.append(rel)              # a stale build copy — the build re-syncs it
        continue
    if cur is None:
        die(f"{rel} is missing")
    die(f"{rel} differs from GitHub main and from the patched version — local edits? "
        f"(commit/stash them or pull main, then re-run)")
if not plan:
    say(f"✓ already applied ({done} file(s) carry {FENCE}) — nothing to do")
    sys.exit(0)

# ── 2. git status: an uncommitted change on a target is a stop sign ──
if "--allow-dirty" not in args:
    try:
        rels = [os.path.relpath(p, repo) for _, p, _, b in plan if not b]
        st = subprocess.run(["git", "status", "--porcelain", "--"] + rels, cwd=repo,
                            capture_output=True, text=True, timeout=30).stdout
        dirty = [l for l in st.splitlines() if l[:2].strip() and not l.startswith("??")]
        if dirty:
            die("uncommitted changes on target files:\n  " + "\n  ".join(dirty) + "\n  (re-run with --allow-dirty to override)")
    except FileNotFoundError:
        say("  (git not found — skipping the status check)")

# ── 3. decode + compile every payload before writing anything ───────
tmp = tempfile.mkdtemp(prefix="broker_truth_")
blobs = {}
for it in ITEMS:
    b = zlib.decompress(base64.b64decode(it["blob"]))
    if sha(b) != it["new"]:
        die(f"payload for {it['path']} is corrupt")
    blobs[it["path"]] = b
    if it["path"].endswith(".py"):
        f = os.path.join(tmp, os.path.basename(it["path"]))
        open(f, "wb").write(b)
        try:
            py_compile.compile(f, doraise=True)
        except py_compile.PyCompileError as e:
            die(f"payload {it['path']} does not compile: {e}")
say(f"payloads verified and compiled ({len(ITEMS)} files)")

# ── 4. write, all or nothing ─────────────────────────────────────────
written = []


def restore():
    for p, old in reversed(written):
        try:
            if old is None:
                os.remove(p)
            else:
                open(p, "wb").write(old)
            bak = p + ".bak-" + FENCE
            if os.path.exists(bak):
                os.remove(bak)
        except Exception as e:
            say(f"  !! could not restore {p}: {e}")


try:
    for it, p, cur, build in plan:
        if cur is not None:
            open(p + ".bak-" + FENCE, "wb").write(cur)
        t = p + ".tmp-" + FENCE
        open(t, "wb").write(blobs[it["path"]])
        os.replace(t, p)
        written.append((p, cur))
        say(f"  wrote {os.path.relpath(p, repo)}{'  (build copy)' if build else ''}")
except Exception as e:
    restore()
    die(f"write failed ({e!r}) — everything restored")
for s_ in skipped:
    say(f"  skipped stale build copy {s_} (the next build re-syncs it)")

# ── 5. tests ─────────────────────────────────────────────────────────
backend = os.path.join(repo, "backend")
py = next((c for c in (os.path.join(backend, "venv", "bin", "python"), os.path.join(backend, ".venv", "bin", "python"),
                       os.path.join(repo, "venv", "bin", "python"), os.path.join(repo, ".venv", "bin", "python"))
           if os.path.exists(c)), sys.executable)
if "--skip-tests" in args:
    say("tests skipped (--skip-tests)")
else:
    say(f"running tests with {py}")
    env = dict(os.environ, PYTHONPATH=backend)
    failed, envmiss = [], []
    for t in TESTS:
        if not os.path.exists(os.path.join(backend, t)):
            continue
        try:
            r = subprocess.run([py, t], cwd=backend, env=env, capture_output=True, text=True, timeout=600)
            outp = (r.stdout or "") + (r.stderr or "")
        except subprocess.TimeoutExpired:
            r, outp = None, "timeout"
        last = (outp.strip().splitlines() or [""])[-1]
        if r is not None and r.returncode == 0:
            say(f"  ✓ {t}  {last}")
        elif "ModuleNotFoundError" in outp and "No module named 'app" not in outp:
            envmiss.append(t)
            say(f"  ? {t}  could not run here: {last}")
        else:
            failed.append(t)
            say(f"  ✗ {t}\n" + "\n".join("      " + l for l in outp.strip().splitlines()[-25:]))
    if failed:
        restore()
        die("tests failed: " + ", ".join(failed) + " — every file restored")
    if envmiss:
        say("  note: some suites need the backend's Python packages; re-run them with that Python")

shutil.rmtree(tmp, ignore_errors=True)
say(f"\n✓ {FENCE} applied ({len(written)} file(s)). Next: ./desktop/build-scalp.sh both, then restart the app.")
say("  Undo: python3 apply_broker_truth.py --rollback")
